package com.hbm.entity.mob.ufo;
import com.hbm.bomb.nuclear.NuclearPlasmaBlastEffects;import com.hbm.entity.projectile.EntityBulletBaseNT;import com.hbm.explosion.ExplosionNukeGeneric;import com.hbm.registry.HbmSounds;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.level.ClipContext;import net.minecraft.world.phys.*;import net.minecraft.sounds.*;
/** Exact GunNPCFactory.getRocketUFOConfig bntUpdate/bntImpact; used only by the unique original NT entity. */
public final class UfoRocketBehavior {
 public static void update(EntityBulletBaseNT bullet){if(bullet.level().isClientSide)return;var data=bullet.getPersistentData();if(bullet.level().getEntity(data.getInt("homingTarget"))==null)choose(bullet);var target=bullet.level().getEntity(data.getInt("homingTarget"));if(target!=null){if(bullet.distanceToSqr(target)<5){impact(bullet);bullet.discard();return;}var delta=new Vec3(target.getX()-bullet.getX(),target.getY()+target.getBbHeight()/2-bullet.getY(),target.getZ()-bullet.getZ()).normalize();double speed=bullet.getDeltaMovement().length();bullet.setDeltaMovement(delta.scale(speed));}}
 private static void choose(EntityBulletBaseNT bullet){LivingEntity target=null;double best=90;var world=bullet.level();for(var e:world.getEntitiesOfClass(LivingEntity.class,bullet.getBoundingBox().inflate(100))){if(!e.isAlive()||e==bullet.getThrower())continue;var delta=new Vec3(e.getX()-bullet.getX(),e.getY()+e.getBbHeight()/2-bullet.getY(),e.getZ()-bullet.getZ());if(world.clip(new ClipContext(bullet.position(),new Vec3(e.getX(),e.getY()+e.getBbHeight()/2,e.getZ()),ClipContext.Block.COLLIDER,ClipContext.Fluid.NONE,bullet)).getType()!=HitResult.Type.MISS)continue;if(e.distanceToSqr(bullet)<10000){double angle=crossAngle(bullet.getDeltaMovement(),delta);if(angle<best){target=e;best=angle;}}}if(target!=null)bullet.getPersistentData().putInt("homingTarget",target.getId());}
 /** Preserve original BobMathUtil: zero vectors can yieldNaN, and exactly180 subtracts180; no intuitive angle clamp changes source target selection. */
 private static double crossAngle(Vec3 a,Vec3 b){double angle=Math.acos(b.dot(a)/(b.length()*a.length()))*180/Math.PI;if(angle>=180)angle-=180;return angle;}
 public static void impact(EntityBulletBaseNT bullet){if(bullet.level().isClientSide)return;var world=bullet.level();world.playSound(null,bullet.getX(),bullet.getY(),bullet.getZ(),HbmSounds.get("entity.ufoBlast"),SoundSource.HOSTILE,5,.9F+world.random.nextFloat()*.2F);world.playSound(null,bullet.getX(),bullet.getY(),bullet.getZ(),SoundEvents.FIREWORK_ROCKET_BLAST,SoundSource.HOSTILE,5,.5F);ExplosionNukeGeneric.dealDamage(world,bullet.getX(),bullet.getY(),bullet.getZ(),10,50);for(int i=0;i<3;i++)NuclearPlasmaBlastEffects.send(world,bullet.getX(),bullet.getY(),bullet.getZ(),0,.75F,1,5,-30+30*i,world.random.nextFloat()*180,100);}
 private UfoRocketBehavior(){}
}
